using Microsoft.EntityFrameworkCore;

class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "AppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 changed the default discriminator property from "Discriminator"
        // to "$type".  Existing documents already store "Discriminator", so we must
        // explicitly keep the old property name to avoid data loss / query failures.
        modelBuilder.Entity<Product>()
            .ToContainer("Products")
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Product>("Product");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

class CosmosService
{
    // EF Core 9 removed synchronous Cosmos DB query support.
    // All queries must use async methods (ToListAsync, FirstAsync, etc.).
    async Task<List<Product>> GetProductsAsync(CosmosContext db)
    {
        return await db.Products.ToListAsync();
    }

    async Task<Product?> FindProductAsync(CosmosContext db, string name)
    {
        return await db.Products.FirstOrDefaultAsync(p => p.Name == name);
    }
}

